[{"order":1,"type":"heading","text":"Unit and Integration Testing Express Apps (Supertest, Jest)"},{"order":2,"type":"paragraph","text":"Testing is a critical part of building robust Express.js applications. While unit tests focus on isolated functions or components, integration tests verify that different parts of your application work together correctly, such as HTTP routes interacting with middleware and databases."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To get started, we need to install Jest as our test runner and assertion library, along with Supertest for making HTTP requests to our Express app without starting a server."},{"order":5,"type":"code","text":"npm install --save-dev jest supertest"},{"order":6,"type":"paragraph","text":"Next, update your package.json file to include the test script:"},{"order":7,"type":"code","text":""scripts": {
  "test": "jest --runInBand"
}"},{"order":8,"type":"subheading","text":"Creating the Express App"},{"order":9,"type":"paragraph","text":"To properly test an Express application with Supertest, it is a best practice to separate your app definition from your server listener. Create an app.js file:"},{"order":10,"type":"code","text":"const express = require('express');
const app = express();

app.use(express.json());

app.get('/api/users', (req, res) => {
  res.status(200).json([{ id: 1, name: 'John Doe' }]);
});

app.post('/api/users', (req, res) => {
  const { name } = req.body;
  if (!name) {
    return res.status(400).json({ error: 'Name is required' });
  }
  res.status(201).json({ id: 2, name });
});

module.exports = app;"},{"order":11,"type":"paragraph","text":"Then create your server.js file to start the listener:"},{"order":12,"type":"code","text":"const app = require('./app');
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log('Server running on port ' + PORT);
});"},{"order":13,"type":"subheading","text":"Writing Integration Tests with Supertest"},{"order":14,"type":"paragraph","text":"Create a test file named app.test.js. We will import Supertest and our Express app to test the API endpoints."},{"order":15,"type":"code","text":"const request = require('supertest');
const app = require('./app');

describe('GET /api/users', () => {
  it('should return a list of users', async () => {
    const response = await request(app).get('/api/users');
    expect(response.status).toBe(200);
    expect(response.body).toEqual([{ id: 1, name: 'John Doe' }]);
  });
});

describe('POST /api/users', () => {
  it('should create a new user', async () => {
    const response = await request(app)
      .post('/api/users')
      .send({ name: 'Jane Doe' });

    expect(response.status).toBe(201);
    expect(response.body).toHaveProperty('id');
    expect(response.body.name).toBe('Jane Doe');
  });

  it('should return 400 if name is missing', async () => {
    const response = await request(app)
      .post('/api/users')
      .send({});

    expect(response.status).toBe(400);
    expect(response.body).toEqual({ error: 'Name is required' });
  });
});"},{"order":16,"type":"subheading","text":"Best Practices"},{"order":17,"type":"bullet_point","text":"Always export your Express app instance without calling .listen() inside the app file to avoid port collision errors during testing."},{"order":18,"type":"bullet_point","text":"Use test databases or mock database calls when writing integration tests that alter persistent data."},{"order":19,"type":"bullet_point","text":"Group related tests using Jest describe blocks and write descriptive it statements."}]
